<?php
declare(strict_types=1);
if(!defined('ABSPATH'))exit;
function stageart_theme_setup():void{add_theme_support('title-tag');add_theme_support('post-thumbnails');add_theme_support('html5',['search-form','comment-form','comment-list','gallery','caption','style','script']);add_theme_support('custom-logo',['height'=>80,'width'=>320,'flex-height'=>true,'flex-width'=>true]);register_nav_menus(['primary'=>'メインメニュー']);}
add_action('after_setup_theme','stageart_theme_setup');
function stageart_theme_assets():void{wp_enqueue_style('stageart-theme',get_stylesheet_uri(),[], '1.3.4');wp_register_script('stageart-theme-inline',false,[], '1.3.4',true);wp_enqueue_script('stageart-theme-inline');wp_add_inline_script('stageart-theme-inline','(function(){function init(){if(!document.body.classList.contains("stageart-performance-labels-off"))return;document.querySelectorAll(".stageart-performance-list-time").forEach(function(el){var walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);var nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(function(node){node.nodeValue=node.nodeValue.replace(/\\s*●/g,"");});});}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init);else init();})();');}
add_action('wp_enqueue_scripts','stageart_theme_assets');
function stageart_theme_production_body_class(array$classes):array{$slug=get_query_var('stageart_production_slug');if(is_string($slug)&&$slug!==''){$q=new WP_Query(['post_type'=>'stageart_production','name'=>$slug,'post_status'=>'publish','posts_per_page'=>1,'fields'=>'ids']);if($q->posts){$use=get_post_meta((int)$q->posts[0],'use_labels',true);if((string)$use!=='1')$classes[]='stageart-performance-labels-off';}}return$classes;}
add_filter('body_class','stageart_theme_production_body_class');
function stageart_theme_org(string $key,string $default=''):string{return(string)get_option('stageart_org_'.$key,$default);}
function stageart_theme_released($value):bool{if(!$value)return true;try{$now=new DateTimeImmutable('now',new DateTimeZone('UTC'));return$now>=new DateTimeImmutable((string)$value,new DateTimeZone('UTC'));}catch(Throwable){return false;}}
function stageart_theme_production_url(WP_Post $post):string{return home_url('/production/'.rawurlencode($post->post_name).'/');}
function stageart_theme_menu_fallback():void{wp_nav_menu(['theme_location'=>'primary','fallback_cb'=>false]);}
function stageart_theme_render_production_card(WP_Post $post):void{$m=get_post_meta($post->ID);$summary=(string)($m['summary'][0]??'');$summary_release=(string)($m['summary_release'][0]??'');$image_id=(int)($m['main_image_id'][0]??0);$image_release=(string)($m['main_image_release'][0]??'');$schedule_start=(string)($m['schedule_start'][0]??'');$schedule_end=(string)($m['schedule_end'][0]??'');echo'<article class="stageart-card"><a class="stageart-card-link" href="'.esc_url(stageart_theme_production_url($post)).'">';if($image_id&&stageart_theme_released($image_release))echo'<div class="stageart-card-image">'.wp_get_attachment_image($image_id,'large').'</div>';else echo'<div class="stageart-card-image" aria-hidden="true"></div>';echo'<div class="stageart-card-body"><h3>'.esc_html($post->post_title).'</h3>';if($schedule_start||$schedule_end)echo'<p class="stageart-card-meta">'.esc_html($schedule_start).($schedule_end?' ～ '.esc_html($schedule_end):'').'</p>';if($summary&&stageart_theme_released($summary_release))echo'<p class="stageart-card-summary">'.esc_html($summary).'</p>';echo'</div></a></article>';}
function stageart_theme_home_sections():array{if(class_exists('StageArtCore\\Presentation\\PublicSite\\SiteStructure'))return StageArtCore\Presentation\PublicSite\SiteStructure::homepageSections();return[];}
function stageart_theme_menu_items():array{if(class_exists('StageArtCore\\Presentation\\PublicSite\\SiteStructure'))return StageArtCore\Presentation\PublicSite\SiteStructure::menuItems();return[];}
function stageart_theme_structure_url(string $type,string $ref):string{if($type==='system'&&class_exists('StageArtCore\\Presentation\\PublicSite\\SiteStructure'))return StageArtCore\Presentation\PublicSite\SiteStructure::systemUrl($ref);if($type==='url')return esc_url_raw($ref);if($type==='production'){$p=get_post((int)$ref);return$p&&$p->post_type==='stageart_production'?stageart_theme_production_url($p):'';}if($type==='free_content'){ $p=get_post((int)$ref);return $p&&$p->post_type==='stageart_free_content'&&$p->post_status==='publish'&&((string)get_post_meta($p->ID,'_stageart_free_owner',true)==='top')?home_url('/content/'.rawurlencode($p->post_name).'/'):'';}if($type==='member'){$m=(new StageArtCore\Domain\Member\MemberRepository())->find((int)$ref);return$m&&($m['status']??'')==='published'&&stageart_theme_released($m['release_at']??null)?home_url('/member/'.rawurlencode((string)$m['slug']).'/'):'';}return'';}
function stageart_theme_render_menu_tree(array$items,string $parent=''):void{$children=array_values(array_filter($items,static fn(array$x):bool=>(string)$x['parent_id']===$parent));if(!$children)return;echo'<ul>';foreach($children as$item){$childrenHere=array_values(array_filter($items,static fn(array$x):bool=>(string)$x['parent_id']===(string)$item['id']));$url=$item['type']==='folder'?'':stageart_theme_structure_url((string)$item['ref_type'],(string)$item['ref_id']);echo'<li>'.($url?'<a href="'.esc_url($url).'">':'<span>').esc_html($item['label']).($url?'</a>':'</span>');if($childrenHere)stageart_theme_render_menu_tree($items,(string)$item['id']);echo'</li>';}echo'</ul>';}
function stageart_theme_render_configured_menu():void{$items=stageart_theme_menu_items();if(!$items){stageart_theme_menu_fallback();return;}echo'<nav class="stageart-nav" aria-label="メインメニュー">';stageart_theme_render_menu_tree($items);echo'</nav>';}
function stageart_theme_render_home_slot(array$slot):void{$type=(string)($slot['type']??'');$ref=(string)($slot['ref']??'');if($type==='system'&&$ref==='productions'){$q=new WP_Query(['post_type'=>'stageart_production','post_status'=>'publish','posts_per_page'=>6,'orderby'=>'date','order'=>'DESC']);if($q->have_posts()){echo'<div class="stageart-production-grid">';while($q->have_posts()){$q->the_post();stageart_theme_render_production_card($q->post);}echo'</div>';}else echo'<p class="stageart-placeholder">現在公開されている公演はありません。</p>';wp_reset_postdata();return;}if($type==='system'&&$ref==='members'){$members=(new StageArtCore\Domain\Member\MemberRepository())->all(true);if(!$members){echo'<p class="stageart-placeholder">現在公開されているメンバーはいません。</p>';return;}echo'<div class="stageart-members">';foreach($members as$m){$url=home_url('/member/'.rawurlencode((string)$m['slug']).'/');echo'<article class="stageart-card"><a class="stageart-card-link" href="'.esc_url($url).'">';echo'<div class="stageart-member-card-image">'.(!empty($m['photo_id'])?wp_get_attachment_image((int)$m['photo_id'],'medium'):'').'</div><div class="stageart-member-card-body"><h2>'.esc_html((string)$m['name']).'</h2></div></a></article>';}echo'</div>';return;}if($type==='system'&&$ref==='representative_greeting'){ $greeting=StageArtCore\Domain\Site\RepresentativeGreeting::get();if(!StageArtCore\Domain\Site\RepresentativeGreeting::isReleased())return;if(!$greeting['member_id']||trim($greeting['body'])==='')return;$member=(new StageArtCore\Domain\Member\MemberRepository())->find($greeting['member_id']);if(!$member||($member['status']??'')!=='published'||!stageart_theme_released($member['release_at']??null))return;$url=home_url('/member/'.rawurlencode((string)$member['slug']).'/');echo'<article class="stageart-representative-greeting"><div class="stageart-representative-greeting-image">'.(!empty($member['photo_id'])?wp_get_attachment_image((int)$member['photo_id'],'large'):'').'</div><div class="stageart-representative-greeting-body"><h2>'.esc_html((string)$member['name']).'</h2><div>'.wp_kses_post(wpautop($greeting['body'])).'</div><p><a class="stageart-button" href="'.esc_url($url).'">プロフィールを見る</a></p></div></article>';return;}if($type==='system'&&$ref==='about'){$desc=stageart_theme_org('description');if($desc)echo'<div class="stageart-feature"><div class="stageart-feature-copy"><div>'.wp_kses_post(wpautop($desc)).'</div></div></div>';return;}if($type==='system'&&$ref==='news'){$q=new WP_Query(['post_type'=>'post','post_status'=>'publish','posts_per_page'=>6,'orderby'=>'date','order'=>'DESC']);if($q->have_posts()){echo'<div class="stageart-news-list">';while($q->have_posts()){$q->the_post();echo'<article class="stageart-news-item"><time class="stageart-news-date" datetime="'.esc_attr(get_the_date('c')).'">'.esc_html(get_the_date('Y.m.d')).'</time><h3><a href="'.esc_url(get_permalink()).'">'.esc_html(get_the_title()).'</a></h3></article>';}echo'</div>';}else echo'<p class="stageart-placeholder">現在公開されているお知らせはありません。</p>';wp_reset_postdata();return;}if($type==='production'){$p=get_post((int)$ref);if($p&&$p->post_status==='publish')stageart_theme_render_production_card($p);return;}if($type==='member'){$m=(new StageArtCore\Domain\Member\MemberRepository())->find((int)$ref);if(!$m||($m['status']??'')!=='published'||!stageart_theme_released($m['release_at']??null))return;echo'<article class="stageart-member-card"><a href="'.esc_url(home_url('/member/'.rawurlencode((string)$m['slug']).'/')).'"><div class="stageart-member-card-image">'.(!empty($m['photo_id'])?wp_get_attachment_image((int)$m['photo_id'],'medium'):'').'</div><div class="stageart-member-card-body"><h2>'.esc_html((string)$m['name']).'</h2></div></a></article>';return;}if($type==='url'&&$ref)echo'<p><a class="stageart-button" href="'.esc_url($ref).'">詳しく見る</a></p>';}
